import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';
class ReminderEditorScreen extends ConsumerStatefulWidget{const ReminderEditorScreen({super.key});@override ConsumerState<ReminderEditorScreen> createState()=>_ReminderEditorScreenState();}
class _ReminderEditorScreenState extends ConsumerState<ReminderEditorScreen>{final title=TextEditingController(),note=TextEditingController();String category='Feeding',repeat='once';DateTime due=DateTime.now().add(const Duration(hours:1));String? petId;@override void dispose(){title.dispose();note.dispose();super.dispose();}
Future<void> save()async{final c=ref.read(appControllerProvider);if(title.text.trim().isEmpty||c.selectedPet==null)return;final r=Reminder(id:DateTime.now().microsecondsSinceEpoch.toString(),petId:petId??c.selectedPet!.id,title:title.text.trim(),category:category,dueAt:due,repeat:repeat,note:note.text.trim());await c.save('reminders',r.toMap());if(mounted)Navigator.pop(context);}
